  4→interface Conversation {
  5→  id: string;
  6→  title: string | null;
  7→  created_at: string;
  8→  updated_at: string;
  9→}
 10→
 11→interface ConversationHistoryProps {
 12→  activeConversationId: string | null;
 13→  onSelect: (conversationId: string) => void;
 14→  onNew: () => void;
 15→  onDelete: (conversationId: string) => void;
 16→  onRename: (conversationId: string, title: string) => void;
 17→  refreshTrigger: number;
