 19→
 20→function timeAgo(dateStr: string): string {
 21→  const date = new Date(dateStr);
 22→  const now = new Date();
 23→  const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);
 24→  if (seconds < 60) return 'just now';
 25→  const minutes = Math.floor(seconds / 60);
 26→  if (minutes < 60) return `${minutes}m ago`;
 27→  const hours = Math.floor(minutes / 60);
 28→  if (hours < 24) return `${hours}h ago`;
 29→  const days = Math.floor(hours / 24);
 30→  if (days < 30) return `${days}d ago`;
 31→  return date.toLocaleDateString();
 32→}
 33→
 34→export function ConversationHistory({
 35→  activeConversationId,
 36→  onSelect,
 37→  onNew,
 38→  onDelete,
 39→  onRename,
 40→  refreshTrigger,
 41→}: ConversationHistoryProps) {
 42→  const [conversations, setConversations] = useState<Conversation[]>([]);
 43→  const [editingId, setEditingId] = useState<string | null>(null);
 44→  const [editTitle, setEditTitle] = useState('');
 45→  const editInputRef = useRef<HTMLInputElement>(null);
 46→
 47→  const fetchConversations = useCallback(async () => {
 48→    try {
 49→      const res = await fetch('/api/conversations');
 50→      if (res.ok) {
 51→        setConversations(await res.json());
 52→      }
 53→    } catch {
 54→      // Sidebar fetch failure: show empty list
 55→    }
 56→  }, []);
 57→
 58→  useEffect(() => {
 59→    fetchConversations();
 60→  }, [fetchConversations, refreshTrigger]);
 61→
 62→  useEffect(() => {
 63→    if (editingId && editInputRef.current) {
 64→      editInputRef.current.focus();
 65→      editInputRef.current.select();
 66→    }
 67→  }, [editingId]);
 68→
 69→  const handleRenameSubmit = (id: string) => {
 70→    const trimmed = editTitle.trim();
 71→    if (trimmed) {
 72→      onRename(id, trimmed);
 73→    }
 74→    setEditingId(null);
 75→  };
 76→
 77→  const handleDelete = (e: React.MouseEvent, id: string) => {
 78→    e.stopPropagation();
 79→    if (confirm('Delete this conversation?')) {
 80→      onDelete(id);
 81→    }
 82→  };
 83→
 84→  const handleStartRename = (e: React.MouseEvent, id: string, currentTitle: string) => {
 85→    e.stopPropagation();
 86→    setEditingId(id);
 87→    setEditTitle(currentTitle || '');
 88→  };
 89→
 90→  return (
 91→    <div className="conv-history">
 92→      <div className="conv-history__header">
 93→        <span className="conv-history__title">Conversations</span>
 94→        <button className="conv-history__new-btn" onClick={onNew} title="New conversation">
 95→          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 96→            <line x1="12" y1="5" x2="12" y2="19" />
 97→            <line x1="5" y1="12" x2="19" y2="12" />
 98→          </svg>
 99→        </button>
100→      </div>
101→      <div className="conv-history__list">
102→        {conversations.length === 0 ? (
103→          <div className="conv-history__empty">No conversations yet</div>
104→        ) : (
105→          conversations.map((conv) => (
106→            <div
107→              key={conv.id}
108→              className={`conv-history__item ${conv.id === activeConversationId ? 'conv-history__item--active' : ''}`}
109→              onClick={() => onSelect(conv.id)}
110→            >
111→              {editingId === conv.id ? (
112→                <input
113→                  ref={editInputRef}
114→                  className="conv-history__edit-input"
115→                  value={editTitle}
116→                  onChange={(e) => setEditTitle(e.target.value)}
117→                  onBlur={() => handleRenameSubmit(conv.id)}
118→                  onKeyDown={(e) => {
119→                    if (e.key === 'Enter') handleRenameSubmit(conv.id);
120→                    if (e.key === 'Escape') setEditingId(null);
121→                  }}
122→                  onClick={(e) => e.stopPropagation()}
123→                />
124→              ) : (
125→                <>
126→                  <div className="conv-history__item-title">
127→                    {conv.title || 'Untitled'}
128→                  </div>
129→                  <div className="conv-history__item-meta">
130→                    <span className="conv-history__item-time">{timeAgo(conv.updated_at)}</span>
131→                    <span className="conv-history__item-actions">
132→                      <button
133→                        className="conv-history__action-btn"
134→                        onClick={(e) => handleStartRename(e, conv.id, conv.title || '')}
135→                        title="Rename"
136→                      >
137→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
138→                          <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
139→                          <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
140→                        </svg>
141→                      </button>
142→                      <button
143→                        className="conv-history__action-btn conv-history__action-btn--danger"
144→                        onClick={(e) => handleDelete(e, conv.id)}
145→                        title="Delete"
146→                      >
147→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
148→                          <polyline points="3 6 5 6 21 6" />
149→                          <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
150→                        </svg>
151→                      </button>
152→                    </span>
153→                  </div>
154→                </>
155→              )}
156→            </div>
157→          ))
158→        )}
159→      </div>
160→    </div>
161→  );
162→}
