258→          onTableClick={handleTableClick}
259→          onTableDelete={handleTableDelete}
260→          onUpload={handleFileUpload}
261→          onDeleteAll={handleDeleteAll}
262→          collapsed={sidebarCollapsed}
263→          onToggle={() => setSidebarCollapsed((prev) => !prev)}
264→          onUseSkill={(name) => setPendingSkillCommand(name)}
265→          activeConversationId={conversation.activeConversationId}
266→          onConversationSelect={handleConversationSelect}
267→          onConversationNew={handleNewConversation}
268→          onConversationDelete={handleConversationDelete}
269→          onConversationRename={handleConversationRename}
270→          conversationRefreshTrigger={conversation.refreshTrigger}
271→        />
272→      </div>
273→      {agentOpen ? (
274→        <div className="app__agent-wrapper">
275→          <div className="app__header">
276→            <h1 className="app__title">{t('appTitle')}</h1>
277→            <div className="app__header-actions">
278→              <button
279→                className="app__lang-toggle"
280→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
281→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
